const b = ($json && $json.body) ? $json.body : $json;
return { json: {
  lead_email:        String(b.lead_email || b.email || '').trim(),
  campaign_id:       String(b.campaign_id || '').trim(),
  campaign_name:     String(b.campaign_name || b.campaign || '').trim(),
  instantly_lead_id: String(b.lead_id || b.leadId || b.instantly_lead_id || '').trim(),
}};

// contact from the GHL search (explicit ref; order-independent)
const r = $('GHL: Search Contact by Email').item.json;
const c = (r.contacts && r.contacts[0]) ? r.contacts[0] : (r.contact || r);
const cf = id => { const f = (c.customFields || []).find(x => x.id === id); return f ? f.value : ''; };

const NOTE_ID='4Ysr9E6CKC2vZK9m6MNm', EVENTLOGS_ID='7D9N71mEDfipN90zfV0j', EMAILHIST_ID='TcdjZt3fwFSZTgY6ngeE', CALLHIST_ID='ZVeEoK85i5EOhWt1HO1F', EMAIL_STEP_NAME_ID='WtFfl1nEbMupk2oR4m9e';

// pick email (newest in the campaign-scoped fetch)
const resp  = ($('Instantly: Get Email').item && $('Instantly: Get Email').item.json) ? $('Instantly: Get Email').item.json : {};
const items = Array.isArray(resp.items) ? resp.items : (Array.isArray(resp) ? resp : []);
const em = items[0] || {};
const emailId  = String((em && em.id) || '').trim();
const bodyHtml = (em && em.body && (em.body.html || em.body.text)) ? String(em.body.html || em.body.text) : '';

// strip HTML -> clean text for the summariser (fewer tokens, cleaner input)
const body_clean = bodyHtml
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&#39;/gi, "'").replace(/&quot;/gi, '"')
  .replace(/\s+/g, ' ').trim();

const oppList = Array.isArray(c.opportunities) ? c.opportunities : [];

// ---- Route: email_step_name decides the target "Cold Email N Sent" stage -----------
// email_step_name is written by the senders as 'cold email 1'..'cold email 4'
// (also 'missed call email N' -> no cold step -> no move; the filter drops it).
const email_step_name = String(cf(EMAIL_STEP_NAME_ID) || '').trim();

const EMAIL_PIPELINE_ID = '1A1RkYaL93s2rqbQ3Opi';
const SENT_STAGE = {
  1: '41849471-6f42-4f40-9692-bbd4d3713d17',   // Cold Email 1 Sent
  2: 'fdd4f9a4-a626-4866-a904-5053e626306f',   // Cold Email 2 Sent
  3: '2f599547-4a2b-4ba4-850d-0feb7fcc976c',   // Cold Email 3 Sent
  4: '39a20e88-ce88-46c6-9e95-8134aa9f269d'    // Cold Email 4 Sent
};
const coldStep = (email_step_name.toLowerCase().match(/^cold email (\d+)$/) || [])[1] || '';
const target_sent_stage_id = coldStep ? (SENT_STAGE[Number(coldStep)] || '') : '';

const emailOpp = oppList.find(o => o && o.pipelineId === EMAIL_PIPELINE_ID) || {};
const email_opp_id = String(emailOpp.id || '');

const now = DateTime.now().setZone('America/Los_Angeles');
const stampNote = now.toFormat('yyyy-MM-dd HH:mm');
const stampRun  = now.toFormat('ccc, LLL d, yyyy, hh:mm a') + ' (PT)';
let stampEmail = stampRun;
const tsRaw = String((em && (em.timestamp_email || em.timestamp_created)) || '').trim();
if (tsRaw) { const dt = DateTime.fromISO(tsRaw).setZone('America/Los_Angeles'); if (dt.isValid) stampEmail = dt.toFormat('ccc, LLL d, yyyy, hh:mm a') + ' (PT)'; }

const step_label = email_step_name || 'email';

// note + event_logs (no AI needed)
const noteBase  = String(cf(NOTE_ID) || '').trim();
const noteEntry = '[' + stampNote + ' | EMAIL_SENT] Cold Email';
const updated_note = noteBase ? (noteBase + '\n' + noteEntry) : noteEntry;
const elBase  = String(cf(EVENTLOGS_ID) || '').trim();
const elEntry = '[' + stampRun + '] ' + step_label + ' sent';
const updated_event_logs = elBase ? (elBase + '\n' + elEntry) : elEntry;

const ehBase = String(cf(EMAILHIST_ID) || '').trim();              // base email_history (appended in logging branch)
const call_history = String(cf(CALLHIST_ID) || '').trim();
const instantly_lead_id = String($('Normalize').item.json.instantly_lead_id || '').trim();

return { json: {
  contact_id: c.id, email_id: emailId,
  body_clean,
  email_step_name, step_label, stampEmail,
  eh_base: ehBase, call_history,
  updated_note, updated_event_logs,
  instantly_lead_id,
  target_sent_stage_id,
  email_opp_id
}};

const p = $('Build Logs + Route').item.json;
const ai = $json || {};
let summary = '';
try { summary = String(ai.choices[0].message.content || '').trim(); } catch (e) { summary = ''; }
if (!summary) summary = p.step_label + ' sent';   // fallback if the summariser errored / returned empty

const ehBase  = String(p.eh_base || '').trim();
const ehEntry = '[' + p.email_id + ' | ' + p.stampEmail + ' | Kevin | ' + p.step_label + '] ' + summary;
const updated_email_history = ehBase ? (ehBase + '\n' + ehEntry) : ehEntry;

return { json: {
  contact_id: p.contact_id,
  updated_note: p.updated_note, updated_event_logs: p.updated_event_logs,
  updated_email_history, call_history: p.call_history,
  email_summary: summary, instantly_lead_id: p.instantly_lead_id
}};

const e  = $('Build email_history').item.json;
const ai = $json || {};
let interaction = '';
try { interaction = String(ai.choices[0].message.content || '').trim(); } catch (err) { interaction = ''; }

const NOTE_ID='4Ysr9E6CKC2vZK9m6MNm', EVENTLOGS_ID='7D9N71mEDfipN90zfV0j', EMAILHIST_ID='TcdjZt3fwFSZTgY6ngeE', LEADID_ID='TWLomDBX0XInU1IKrG8L', INTERACTION_ID='AH3JqyYEPzPX4wXKoX1V';

const customFields = [
  { id: NOTE_ID,      value: e.updated_note },
  { id: EVENTLOGS_ID, value: e.updated_event_logs },
  { id: EMAILHIST_ID, value: e.updated_email_history },
];
// Interaction Summary is OVERWRITE (rolling snapshot). Only write if the AI produced one,
// so a model hiccup never blanks an existing summary.
if (interaction) customFields.push({ id: INTERACTION_ID, value: interaction });
const lead_id = String(e.instantly_lead_id || '').trim();
if (lead_id) customFields.push({ id: LEADID_ID, value: lead_id });

return { json: { contact_id: e.contact_id, customFields, interaction_summary: interaction } };
